   440	                i += 1;
   441	
   442	                if (ch != '\r') {
   443	                    buf[buf_i] = ch;
   444	                    buf_i += 1;
   445	                    continue;
   446	                }
   447	
   448	                // CRLF
   449	                buf[buf_i] = '\r';
   450	                buf[buf_i + 1] = '\n';
   451	                buf_i += 2;
   452	            }
   453	
   454	            break :slice buf[0..buf_i];
   455	        };
